import{_ as s,C as o,o as r,c as n,a5 as t,E as c,j as a,a as l}from"./chunks/framework.BwlBv862.js";const y=JSON.parse('{"title":"Revisar cambios según el área","description":"","frontmatter":{"title":"Revisar cambios según el área","docId":"user.cloud.changes","translationKey":"user.cloud.changes","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f875a22e66dd822d7ea1344188d8b7b087a23a777e072240a4a3c7c57969f995","translationRevision":"d10088ad911ff785cebe9428728c8e59cd631360c910325f228057363ac6e9c8","order":20},"headers":[],"relativePath":"es/user/cloud/changes.md","filePath":"es/user/cloud/changes.md","lastUpdated":1794611623000}'),d={name:"es/user/cloud/changes.md"};function u(p,e,v,m,b,g){const i=o("DemoFrame");return r(),n("div",null,[e[0]||(e[0]=t('<h1 id="review-changes-by-area" tabindex="-1">Revisar cambios según el área <a class="header-anchor" href="#review-changes-by-area" aria-label="Permalink to &quot;Revisar cambios según el área {#review-changes-by-area}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Comprende qué compara un panel <strong>Changes</strong> antes de restablecer, enviar o adoptar datos. Necesitas contenido local guardado. Las operaciones Cloud también requieren un host compatible, el modo de sincronización pertinente y una <a href="./account.html">cuenta autenticada</a>. Los paneles con el mismo nombre no realizan necesariamente el mismo transporte.</p><h2 id="review-events-and-actions-locally" tabindex="-1">Revisar Eventos y Acciones localmente <a class="header-anchor" href="#review-events-and-actions-locally" aria-label="Permalink to &quot;Revisar Eventos y Acciones localmente {#review-events-and-actions-locally}&quot;">​</a></h2><ol><li>Abre <strong>Automations</strong>, selecciona Events o Actions y entra en <strong>Changes</strong>.</li><li>Lee el aviso: esta área compara las definiciones actuales con una referencia conservada en este dispositivo. La primera visita con datos cargados crea esa referencia, por lo que puede no mostrar diferencias.</li><li>Selecciona un registro añadido, modificado o eliminado e inspecciona los valores anterior y posterior.</li><li>Usa <strong>Mark as reviewed</strong> únicamente para convertir la sección actual en la nueva referencia local. No sube definiciones ni aprueba ejecución delegada.</li><li>Usa <strong>Reset</strong> solo si deseas recuperar la referencia. Para un registro recién añadido, lo elimina; para uno modificado o borrado, restaura la definición conservada. Exporta antes si necesitas guardar el estado actual.</li></ol><p>El adaptador de Eventos/Acciones no dispone de colección Cloud para definiciones individuales en esta versión. Una comparación limpia no constituye una copia en Cloud ni demuestra que otro equipo recibió tus cambios.</p><h2 id="review-variables-and-plugins-explicitly" tabindex="-1">Revisar Variables y Plugins explícitamente <a class="header-anchor" href="#review-variables-and-plugins-explicitly" aria-label="Permalink to &quot;Revisar Variables y Plugins explícitamente {#review-variables-and-plugins-explicitly}&quot;">​</a></h2><p>Variables tiene intercambio nativo revisado: guarda localmente, consulta propuestas, inspecciona la comparación y envía, aplica/adopta o retira de forma explícita. Los valores secretos o bloqueados permanecen ocultos y no pueden enviarse por esa ruta. Guardar localmente nunca sube datos. Consulta <a href="./../automations/variables.html">Variables</a>.</p><p>Changes de Plugins utiliza su espacio de sincronización compatible para selecciones y ajustes preparados. Publica por sección, sin un envío independiente por cada fila. Los ajustes muestran nombres de claves modificadas sin revelar valores; los conflictos permiten elegir la versión local o Cloud, sin mezclar campos arbitrariamente. Lee la acción de sección y el modo seleccionado antes de publicar.</p><p>Las superposiciones Cloud usan el flujo de creación/revisión de <a href="./../overlays/">biblioteca y editor</a>. Esta versión base no incluye un adaptador Changes compartido para ellas.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, estado y recuperación <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, estado y recuperación {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Están disponibles la comparación local y el intercambio nativo según capacidades en sus áreas respectivas. Las operaciones remotas dependen del servicio; no se implica aceptación en producción. Si una revisión caduca, actualiza y compara otra vez. Si el resultado no está confirmado, inspecciona estado e historial antes de crear otra operación. Un tiempo de espera agotado no demuestra que nada haya cambiado.</p>',12)),c(i,{scenario:"cloud",locale:"es",tour:"changes",title:"Demo de cloud"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[l("Detalles de operación "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Detalles de operación {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Antes de preparar/migrar v1 → v2, respalda datos y coordina versiones compatibles en todos los dispositivos. En setup prepara, comprueba compatibilidad y previsualiza; revisa conteos seleccionados, pendientes, conflictos y solo-v1 sin asumir sincronización. Exigir cabecera de época es irreversible para escrituras v2 de toda la cuenta y puede rechazar equipos antiguos. Un timeout de barrera es ambiguo; repetirla vuelve a avanzarla. Recarga estado de época/migración y vista previa antes de actuar. Leer época no prueba escrituras anteriores completadas.",-1)),e[3]||(e[3]=a("p",null,"La recuperación depende del modo: Changes de Eventos/Acciones compara referencias locales, sin escritura Cloud. Para Variables/Plugins revisados, recarga comparaciones caducadas y revisa revisión, cuenta e inventarios. Si faltan plugins, usa revisión/reparación de inventario en setup y otra vista previa. Ante intención incierta conserva ID/evidencia y consulta historia/estado; la recuperación técnica exige revisión nueva de entradas congeladas y revisión Cloud. Reanudar esa intención no envía por sí solo una escritura remota. Si no puedes reconciliar, detente sin crear mutación sustituta.",-1))])}const f=s(d,[["render",u]]);export{y as __pageData,f as default};
